((SELECT id FROM evaluaciones WHERE codigo = 'EV_POS_09_F66D8729FC11' AND proyecto_id = @proyecto_id LIMIT 1), (SELECT id FROM indicadores WHERE proyecto_id = @proyecto_id AND tipo_evaluacion = 'Postventa' AND orden = 8 LIMIT 1), '¿Explicó los repuestos reemplazados?', 'Sí', '1', 'Explica al cliente.'),
